python3 << 'EOF'
def digits_base(n, base):
    if n == 0:
        return [0]
    digits = []
    while n > 0:
        digits.append(n % base)
        n //= base
    return digits[::-1]

def in_setA(n):
    digs = digits_base(n, 3)
    return all(d <= 1 for d in digs)

def in_setB(n):
    digs = digits_base(n, 4)
    return all(d <= 1 for d in digs)

# Check 62
print(f"62 in base 3: {digits_base(62, 3)} -> in setA: {in_setA(62)}")
print(f"62 in base 4: {digits_base(62, 4)} -> in setB: {in_setB(62)}")

# Check all pairs (a, b) where a + b = 62
print("\nChecking 62 = a + b:")
found = False
for a in range(63):
    if in_setA(a):
        b = 62 - a
        if in_setB(b):
            print(f"  FOUND: {a} + {b} = 62 (a in setA, b in setB)")
            found = True

if not found:
    print("  No pairs found! 62 ∉ setAB ✓")

# Also check elements of setA and setB
print("\nElements of setA ≤ 62:", [n for n in range(63) if in_setA(n)])
print("Elements of setB ≤ 62:", [n for n in range(63) if in_setB(n)])
EOF
